"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2174],{72174:e=>{e.exports=JSON.parse('{"docs":[{"id":"air-handler-maintenance","title":"Air Handler Maintenance Guide","sourceType":"manual","chunks":[{"id":"air-handler-maintenance_chunk_0","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Overview"],"text":"The air handler (or fan coil) circulates conditioned air through the home. Regular maintenance prevents efficiency loss, water damage, and early equipment failure.","wordCount":23},{"id":"air-handler-maintenance_chunk_1","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Blower Assembly","Blower Motor"],"text":"### Blower Wheel Cleaning\\nA dirty blower wheel loses up to 30% efficiency. Signs: reduced airflow, higher energy bills.\\n\\n**Procedure:**\\n1. Disconnect power at disconnect and breaker\\n2. Remove blower compartment door\\n3. Slide out blower assembly (note wire routing)\\n4. Clean wheel with stiff brush and coil cleaner\\n5. Rinse with water, allow to dry completely before reinstalling\\n6. Check wheel balance — replace if bent or cracked\\n\\n### Blower Motor\\n- **PSC motors:** Lubricate oil ports with 3-in-1 or SAE 20 non-detergent oil (2–3 drops each port) if not factory-sealed\\n- **ECM (variable speed) motors:** Factory sealed, no lubrication needed\\n- Check run capacitor for PSC motors — most air handler motor failures start with a failed capacitor\\n\\n**Normal amp draw:** Should be within 10% of nameplate FLA","wordCount":130},{"id":"air-handler-maintenance_chunk_2","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Evaporator Coil","Inspecting for Leaks"],"text":"### Cleaning\\n- Access panel removal required — coil cleaning is more involved than condenser\\n- Apply no-rinse evaporator coil cleaner; allow to drain through condensate system\\n- Never use acidic cleaners on aluminum coils\\n\\n### Inspecting for Leaks\\n- Look for oil staining around coil connections\\n- Check for low refrigerant symptoms (low suction pressure, high superheat)\\n- Formicary corrosion: small pinholes, hard to detect — consider dye if recurring low charge","wordCount":73},{"id":"air-handler-maintenance_chunk_3","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Condensate System","Common Clog Locations"],"text":"### Drain Line Maintenance\\n- Flush annually with condensate cleaner or 50/50 bleach/water\\n- Install condensate pan tablets (algaecide) to prevent buildup\\n- Verify float switch operation — should cut unit off if pan fills\\n\\n### Common Clog Locations\\n1. At the P-trap (if installed)\\n2. At the PVC elbow near the unit\\n3. Where drain exits to exterior (check for wasp nests or debris)","wordCount":65},{"id":"air-handler-maintenance_chunk_4","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Filter Slot Inspection"],"text":"- Verify filter fits snugly — air bypassing filter goes straight to blower wheel and coil\\n- Check for damaged filter frame or bypass gaps\\n- Consider upgrading to media cabinet for high-MERV filtration without pressure drop","wordCount":37},{"id":"air-handler-maintenance_chunk_5","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Electrical Connections"],"text":"- Tighten all wire terminals in unit disconnect and air handler control box\\n- Check for signs of overheating at wire connections (discoloration, melted insulation)\\n- Verify 24V transformer output: should measure 24–28V AC","wordCount":34}],"totalChunks":6,"createdAt":"2026-10-03T15:40:24.892Z"},{"id":"capacitor-sizing-guide","title":"Capacitor Sizing Guide","sourceType":"guide","chunks":[{"id":"capacitor-sizing-guide_chunk_0","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Overview"],"text":"Run capacitors store electrical energy and provide the phase shift needed to start and run single-phase AC motors. Selecting the correct capacitor is critical — an under- or over-rated capacitor causes motor failure.","wordCount":33},{"id":"capacitor-sizing-guide_chunk_1","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Reading the Nameplate"],"text":"Every capacitor is rated in microfarads (\xb5F) and volts. The rating is printed on the side:\\n- **Dual run capacitor:** Two ratings separated by a slash (e.g., `45/5 \xb5F, 440V`). The higher value runs the compressor; the lower value runs the condenser fan motor.\\n- **Single run capacitor:** One rating (e.g., `35 \xb5F, 370V`).","wordCount":54},{"id":"capacitor-sizing-guide_chunk_2","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Common Carrier Unit Ratings"],"text":"| Model | Compressor Cap (\xb5F) | Fan Cap (\xb5F) | Voltage |\\n|-------|--------------------|-----------|----|\\n| 24ACC624A003 | 40 | 5 | 440V |\\n| 24ACC636A003 | 45 | 5 | 440V |\\n| 24ACC648A003 | 50 | 5 | 440V |\\n| 24ACC660A003 | 55 | 7.5 | 440V |\\n| 24ABB336A003 | 35 | 5 | 370V |","wordCount":59},{"id":"capacitor-sizing-guide_chunk_3","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Tolerance Rules"],"text":"Capacitors are rated with a \xb16% tolerance. A capacitor measuring outside 10% of nameplate value should be replaced. Test with a capacitor meter — **never test capacitors with a standard multimeter**.","wordCount":31},{"id":"capacitor-sizing-guide_chunk_4","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Voltage Ratings"],"text":"A 440V capacitor can safely replace a 370V in the same circuit. Never install a lower voltage rating than specified.","wordCount":20},{"id":"capacitor-sizing-guide_chunk_5","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Failure Signs"],"text":"- Bulging or swollen top — definitive failure\\n- Capacitance reading >10% below nameplate\\n- Burn marks or physical damage\\n- Unit runs but draws high amperage","wordCount":27}],"totalChunks":6,"createdAt":"2026-10-03T15:40:24.894Z"},{"id":"common-ac-error-codes","title":"Common AC Error Codes","sourceType":"manual","chunks":[{"id":"common-ac-error-codes_chunk_0","docId":"common-ac-error-codes","docTitle":"Common AC Error Codes","sourceType":"manual","headingPath":["Common AC Error Codes","Carrier ComfortLink II Error Codes"],"text":"| Code | Description | Likely Cause | Action |\\n|------|-------------|-------------|--------|\\n| E1 | Indoor/outdoor communication fault | Wiring issue, board failure | Check communication wiring between indoor and outdoor units |\\n| E2 | Indoor unit thermistor fault | Thermistor open or shorted | Test thermistor resistance; replace if out of spec |\\n| E3 | Outdoor unit high pressure fault | Overcharge, dirty coil, failed fan | Check refrigerant charge, clean coil, verify fan operation |\\n| E4 | Outdoor unit low pressure fault | Undercharge, leak, restricted filter drier | Check charge, inspect for leaks, replace drier |\\n| E5 | Compressor high temperature | Low airflow, overcharge, dirty coil | Inspect airflow, check refrigerant, clean coil |\\n| E6 | Communication error indoor/outdoor | Control board fault | Power cycle; replace board if persistent |\\n| E8 | Indoor overflow switch open | Clogged drain, stuck float | Clear drain, clean pan, verify float switch |","wordCount":160},{"id":"common-ac-error-codes_chunk_1","docId":"common-ac-error-codes","docTitle":"Common AC Error Codes","sourceType":"manual","headingPath":["Common AC Error Codes","Trane XR Series Error Codes (flash codes)"],"text":"| Flashes | Description |\\n|---------|-------------|\\n| 2 | High pressure lockout |\\n| 3 | Low pressure lockout |\\n| 4 | Open high pressure switch |\\n| 5 | Open low pressure switch |\\n| 6 | Compressor fault |\\n| 7 | Outdoor fan fault |","wordCount":49},{"id":"common-ac-error-codes_chunk_2","docId":"common-ac-error-codes","docTitle":"Common AC Error Codes","sourceType":"manual","headingPath":["Common AC Error Codes","Goodman / Amana LED Flash Codes"],"text":"| LED Pattern | Description |\\n|-------------|-------------|\\n| 1 flash | Normal operation |\\n| 2 flashes | High pressure fault |\\n| 3 flashes | Low pressure fault |\\n| 4 flashes | Open circuit (thermistor or board) |\\n| 5 flashes | Condensate overflow |\\n| Continuous | Check thermostat signal |","wordCount":54},{"id":"common-ac-error-codes_chunk_3","docId":"common-ac-error-codes","docTitle":"Common AC Error Codes","sourceType":"manual","headingPath":["Common AC Error Codes","General Troubleshooting Notes"],"text":"- Always note error codes before power cycling — some codes clear on reset\\n- Document codes on the job work order for warranty purposes\\n- Repeated E3/E4 codes after clearing usually indicate refrigerant system issues, not electrical","wordCount":38}],"totalChunks":4,"createdAt":"2026-10-03T15:40:24.895Z"},{"id":"company-policies","title":"Northwind Heating & Air — Company Policies","sourceType":"policy","chunks":[{"id":"company-policies_chunk_0","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Service Area"],"text":"Austin metro area including: Austin, Round Rock, Cedar Park, Pflugerville, Georgetown, Kyle, Buda, and Manor. Standard service up to 40 miles from our shop at 2400 S Lamar Blvd.","wordCount":29},{"id":"company-policies_chunk_1","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Hours of Operation"],"text":"- **Standard service:** Monday–Saturday, 7:00 AM – 7:00 PM\\n- **Emergency service:** 24 hours/day, 7 days/week (answered by Ava, dispatched to on-call tech)\\n- **Office/phone:** Monday–Friday, 8:00 AM – 6:00 PM","wordCount":31},{"id":"company-policies_chunk_2","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Pricing Policy"],"text":"- All pricing is from the approved price book — technicians may not quote custom prices\\n- Diagnostic / service call fee: $89 (applied toward repair if customer proceeds)\\n- Emergency after-hours call fee: $195 (in addition to repair costs)\\n- All prices include standard labor; unusual access situations may require supervisor approval for premium","wordCount":55},{"id":"company-policies_chunk_3","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Approval Thresholds"],"text":"| Amount | Approval Required |\\n|--------|-----------------|\\n| Up to $499 | Tech authorized to proceed with customer approval |\\n| $500–$4,999 | Customer signature on estimate required |\\n| $5,000+ | Owner (Maria Lopez) approval required before presenting to customer |\\n| Refunds >$100 | Owner approval required |\\n| Discounts >10% | Owner approval required |","wordCount":58},{"id":"company-policies_chunk_4","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Comfort Club Membership Plans"],"text":"| Tier | Monthly Rate | Included | Discount on Repairs |\\n|------|-------------|---------|-------------------|\\n| Basic | $12.99 | 1 tune-up/year | 10% |\\n| Comfort | $19.99 | 2 tune-ups/year | 15% |\\n| Premier | $29.99 | 2 tune-ups + priority + free service call | 20% |\\n\\nMembers get priority scheduling — their jobs are booked before non-member same-day requests.","wordCount":62},{"id":"company-policies_chunk_5","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Customer Communication Standards"],"text":"- All customers receive a text/email confirmation within 5 minutes of booking\\n- Tech sends \\"on my way\\" notification when departing for job\\n- All calls are answered within 3 rings (by Ava, 24/7)\\n- Complaints escalated to dispatcher within 1 business day","wordCount":43},{"id":"company-policies_chunk_6","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Technician Conduct"],"text":"- Wear Northwind uniform and shoe covers in customer homes\\n- Present good/better/best estimate — never pressure customers\\n- Never discuss competitor pricing or criticize competitor work\\n- If a job scope exceeds tech\'s certification, call dispatcher before proceeding\\n- All findings must be documented with photos in the job work order","wordCount":52},{"id":"company-policies_chunk_7","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Warranty Claims"],"text":"See warranty-terms.md for full warranty policy.\\n- Labor warranty: 90 days on all repair work\\n- Parts warranty: Pass-through of manufacturer warranty\\n- New equipment: 10-year parts (registered) / 1-year labor","wordCount":31}],"totalChunks":8,"createdAt":"2026-10-03T15:40:24.895Z"},{"id":"compressor-diagnosis","title":"Compressor Diagnosis","sourceType":"manual","chunks":[{"id":"compressor-diagnosis_chunk_0","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","Overview"],"text":"The compressor is the heart of the refrigeration cycle — and the most expensive component to replace. Accurate diagnosis before condemning a compressor saves customers thousands of dollars.","wordCount":28},{"id":"compressor-diagnosis_chunk_1","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","Electrical Tests","Amperage Test (compressor running)"],"text":"### Resistance Test (compressor off, disconnected)\\nMeasure resistance between terminals C, R, and S:\\n- C–R (common to run): typically 2–8 Ω\\n- C–S (common to start): typically 3–12 Ω  \\n- R–S (run to start): should equal C–R + C–S\\n\\n**Failed if:** Any reading is open (OL) or shorted to ground (test each terminal to chassis ground — should be OL).\\n\\n### Amperage Test (compressor running)\\nCompare measured amps to nameplate RLA (Rated Load Amps):\\n- Within 10% of RLA: normal\\n- >115% of RLA: overloaded — check for high head pressure, low charge, or mechanical issue\\n- <50% of RLA with no cooling: possible open winding or valve failure","wordCount":110},{"id":"compressor-diagnosis_chunk_2","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","Mechanical Tests","Locked Rotor"],"text":"### Compressor Valve Test\\nIf suction pressure rises when compressor shuts off (equalization test):\\n1. Let system run 15 minutes\\n2. Shut off compressor (disconnect Y wire)\\n3. Watch suction pressure — should hold or rise slowly\\n4. **If suction rises to discharge level within 60 seconds:** compressor valves are failed\\n\\n### Locked Rotor\\n- Compressor hums but won\'t start, trips on thermal overload\\n- May indicate: failed start capacitor, failed run capacitor, failed start relay, or mechanical lock\\n- Test capacitors first (fastest fix)\\n- Hard start kit can help marginal compressors","wordCount":93},{"id":"compressor-diagnosis_chunk_3","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","Oil Failures"],"text":"- **Slugging (liquid refrigerant in oil):** Loud banging on startup, especially after long off cycle. Crankcase heater prevents this.\\n- **Oil loss:** Often caused by refrigerant migration — compressor overheats, wears rapidly","wordCount":32},{"id":"compressor-diagnosis_chunk_4","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","When to Replace vs. Repair"],"text":"- Compressor ≤5 years: attempt repair if electrical (capacitor, contactor)\\n- Compressor 6–10 years with catastrophic failure: get second opinion on replacement vs. repair\\n- Compressor >10 years: recommend full system replacement — compressor replacement alone rarely cost-effective\\n- **Never replace compressor without finding and fixing root cause of failure**","wordCount":50}],"totalChunks":5,"createdAt":"2026-10-03T15:40:24.896Z"},{"id":"ductwork-inspection","title":"Ductwork Inspection Checklist","sourceType":"manual","chunks":[{"id":"ductwork-inspection_chunk_0","docId":"ductwork-inspection","docTitle":"Ductwork Inspection Checklist","sourceType":"manual","headingPath":["Ductwork Inspection Checklist","Visual Inspection Points","Common Problem Areas"],"text":"### Supply Ductwork\\n- Check all duct connections at air handler for gaps or separation\\n- Inspect flex duct for kinks, tears, or disconnected sections\\n- Verify all supply registers are open and unobstructed\\n- Check insulation on supply ducts in unconditioned spaces (attics, crawl spaces) — should be R-8 minimum in Texas\\n\\n### Return Ductwork\\n- Inspect return grille filter for blockage\\n- Check return plenum for air leaks (can cause attic air infiltration)\\n- Verify adequate return air path in all rooms (undercut doors or transfer grilles)\\n\\n### Common Problem Areas\\n1. **Flex duct in attics:** Often kinked, over-extended, or disconnected at boots\\n2. **Main trunk connections:** Sheet metal screws missing, tape failing\\n3. **Boot-to-floor connections:** Often unsealed, causing conditioned air to enter under-floor spaces\\n4. **Air handler connections:** Should be sealed with mastic, not just tape","wordCount":139},{"id":"ductwork-inspection_chunk_1","docId":"ductwork-inspection","docTitle":"Ductwork Inspection Checklist","sourceType":"manual","headingPath":["Ductwork Inspection Checklist","Duct Leakage Testing"],"text":"A blower door test or duct blaster test measures duct leakage. Texas standards:\\n- New construction: <4% total leakage at 25 Pa\\n- Existing systems: No formal standard, but >25% leakage warrants attention","wordCount":33},{"id":"ductwork-inspection_chunk_2","docId":"ductwork-inspection","docTitle":"Ductwork Inspection Checklist","sourceType":"manual","headingPath":["Ductwork Inspection Checklist","Sealing Materials"],"text":"- **Mastic sealant:** Best for rigid sheet metal connections — durable, flexible\\n- **Foil tape (UL-listed):** Acceptable for small gaps, not for large leaks\\n- **Avoid:** Standard cloth duct tape — fails within 1–2 years","wordCount":35},{"id":"ductwork-inspection_chunk_3","docId":"ductwork-inspection","docTitle":"Ductwork Inspection Checklist","sourceType":"manual","headingPath":["Ductwork Inspection Checklist","Duct Sizing Notes"],"text":"Undersized ductwork is a common cause of comfort complaints. As a rule of thumb:\\n- Each 100 CFM requires approximately 1 sq inch of duct area\\n- 8\\" round duct carries ~200 CFM at 0.08\\" WC static pressure\\n- Consult Manual D for accurate sizing calculations","wordCount":46}],"totalChunks":4,"createdAt":"2026-10-03T15:40:24.896Z"},{"id":"emergency-procedures","title":"Emergency Procedures","sourceType":"guide","chunks":[{"id":"emergency-procedures_chunk_0","docId":"emergency-procedures","docTitle":"Emergency Procedures","sourceType":"guide","headingPath":["Emergency Procedures","Gas Smell (Suspected Leak)"],"text":"**Immediate actions:**\\n1. Do NOT operate any electrical switches, light switches, or appliances\\n2. Do NOT use your phone inside the building\\n3. Evacuate the building immediately\\n4. Leave the door open as you exit\\n5. Once outside and at a safe distance, call 911 and your gas provider\\n6. Do NOT return to the building until cleared by emergency responders\\n\\n**Northwind policy:** Any call involving gas smell is immediately transferred to our on-call emergency team. We do not attempt to diagnose or schedule over the phone — the customer is directed to evacuate immediately.","wordCount":95},{"id":"emergency-procedures_chunk_1","docId":"emergency-procedures","docTitle":"Emergency Procedures","sourceType":"guide","headingPath":["Emergency Procedures","Carbon Monoxide (CO) Alert"],"text":"Signs of CO: headache, dizziness, nausea, confusion (symptoms improve when leaving the building).\\n\\n1. Evacuate immediately — leave doors open\\n2. Call 911\\n3. Do not re-enter until cleared by fire department\\n4. Northwind emergency team responds within 2 hours for CO-related service calls\\n\\n**CO sources in HVAC:** Cracked heat exchanger, backdrafting furnace, blocked flue, carbon buildup in combustion chamber.","wordCount":60},{"id":"emergency-procedures_chunk_2","docId":"emergency-procedures","docTitle":"Emergency Procedures","sourceType":"guide","headingPath":["Emergency Procedures","No Heat with Vulnerable Occupants"],"text":"When a customer reports no heat and mentions elderly occupants, infants, or people with medical conditions, Northwind treats this as an emergency call:\\n- Same-day service guaranteed (or we coordinate a temporary heater delivery)\\n- Priority tech dispatched regardless of current schedule","wordCount":42},{"id":"emergency-procedures_chunk_3","docId":"emergency-procedures","docTitle":"Emergency Procedures","sourceType":"guide","headingPath":["Emergency Procedures","Electrical Emergency at Unit"],"text":"If a customer reports sparks, burning smell, or smoke from HVAC equipment:\\n1. Advise them to cut power at the disconnect box or main breaker\\n2. Do NOT attempt to operate or reset the equipment\\n3. Schedule an emergency visit\\n\\n**Technician safety:** Before working on any system reporting electrical issues, verify power is off at both the unit disconnect AND the main panel. Test for voltage with a non-contact tester.","wordCount":70}],"totalChunks":4,"createdAt":"2026-10-03T15:40:24.896Z"},{"id":"furnace-igniter-replacement","title":"Furnace Igniter Replacement","sourceType":"manual","chunks":[{"id":"furnace-igniter-replacement_chunk_0","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Types of Igniters","Spark Igniter"],"text":"### Hot Surface Igniter (HSI)\\nThe most common type in modern gas furnaces. A silicon nitride or silicon carbide element heats to ~1800\xb0F when energized, igniting the gas burner.\\n\\n- **Silicon carbide:** Older, more brittle, turns orange-red when working. Resistance: 40–70 Ω when cold.\\n- **Silicon nitride:** Newer, more durable, glows yellow-white. Resistance: 15–50 Ω when cold.\\n\\n### Spark Igniter\\nUsed in some older units. Creates a spark arc to ignite the burner. Look for cracked porcelain or carbon tracking as failure indicators.","wordCount":83},{"id":"furnace-igniter-replacement_chunk_1","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Diagnostic Steps"],"text":"1. Set thermostat to Heat, observe igniter through inspection port\\n2. Igniter should glow within 30–45 seconds of call for heat\\n3. If no glow: measure 120V at igniter leads (verify voltage present)\\n4. If voltage present, no glow: igniter is open — replace\\n5. Measure resistance: out-of-spec reading indicates impending failure","wordCount":52},{"id":"furnace-igniter-replacement_chunk_2","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Resistance Quick Reference"],"text":"| Igniter Type | Good Range | Replace If |\\n|-------------|-----------|-----------|\\n| Silicon carbide | 40–70 Ω | >100 Ω or open circuit |\\n| Silicon nitride | 15–50 Ω | >60 Ω or open circuit |","wordCount":37},{"id":"furnace-igniter-replacement_chunk_3","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Replacement Procedure"],"text":"1. **Disconnect power** — 120V can cause serious injury\\n2. Turn off gas supply at unit shutoff\\n3. Remove burner compartment door\\n4. Unplug igniter harness connector\\n5. Remove mounting screw (usually M4 or 6-32 screw)\\n6. Handle new igniter by the harness only — oils from skin reduce lifespan\\n7. Install new igniter, restore connections\\n8. Test: call for heat, verify ignition within 2 ignition cycles","wordCount":67},{"id":"furnace-igniter-replacement_chunk_4","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Common Brands by Unit"],"text":"- Carrier/Bryant/Payne: HSI, silicon nitride, part 33331012000\\n- Trane/American Standard: HSI, silicon nitride, various by model\\n- Lennox: HSI, silicon carbide (older) or nitride (post-2010)\\n- Goodman/Amana: HSI, silicon nitride, part B1401015S","wordCount":32}],"totalChunks":5,"createdAt":"2026-10-03T15:40:24.897Z"},{"id":"heat-pump-defrost-cycle","title":"Heat Pump Defrost Cycle","sourceType":"manual","chunks":[{"id":"heat-pump-defrost-cycle_chunk_0","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","Why Defrost is Necessary"],"text":"In heating mode, the outdoor coil acts as the evaporator and absorbs heat from outdoor air. When outdoor temperatures fall below ~40\xb0F, moisture in the air freezes on the coil, reducing airflow and efficiency. The defrost cycle reverses this by temporarily switching the unit to cooling mode, using hot refrigerant to melt the ice.","wordCount":54},{"id":"heat-pump-defrost-cycle_chunk_1","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","How the Defrost Cycle Works"],"text":"1. Unit is in heating mode\\n2. Defrost board monitors outdoor coil temperature via thermistor\\n3. When coil temp drops below threshold (typically 26\xb0F) AND timer condition is met, defrost initiates\\n4. Reversing valve switches to cooling mode\\n5. Outdoor fan stops (prevents cold air from slowing defrost)\\n6. Indoor auxiliary heat may energize to compensate for temporary cooling effect\\n7. Defrost terminates when: coil reaches ~57\xb0F, OR 10-minute timeout reached\\n8. Unit returns to heating mode","wordCount":77},{"id":"heat-pump-defrost-cycle_chunk_2","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","Defrost Board Operation"],"text":"Most residential heat pumps use a demand defrost board (vs. time-only boards). Demand boards compare:\\n- **Outdoor coil temperature** (via coil thermistor)\\n- **Outdoor ambient temperature** (via ambient thermistor)\\n- **Timer setting** (5, 30, 60, 90 minutes between defrost checks)","wordCount":40},{"id":"heat-pump-defrost-cycle_chunk_3","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","Troubleshooting Defrost Problems"],"text":"| Symptom | Possible Cause | Check |\\n|---------|---------------|-------|\\n| Unit always in defrost | Short in coil thermistor | Test thermistor resistance |\\n| Unit never defrosts | Open coil thermistor, board fault | Test thermistor, check 24V to board |\\n| Partial defrost (ice remains) | Low charge, dirty coil, fan issue | Check charge, clean coil, verify fan |\\n| Indoor blows cold during defrost | Missing aux heat signal | Check aux heat operation |","wordCount":79},{"id":"heat-pump-defrost-cycle_chunk_4","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","Thermistor Resistance (typical)"],"text":"| Temperature | Resistance |\\n|------------|-----------|\\n| 30\xb0F | ~16,000 Ω |\\n| 40\xb0F | ~12,000 Ω |\\n| 57\xb0F | ~7,500 Ω |\\n\\nReplace thermistor if resistance is open or significantly out of range.","wordCount":35}],"totalChunks":5,"createdAt":"2026-10-03T15:40:24.897Z"},{"id":"indoor-air-quality","title":"Indoor Air Quality (IAQ) Solutions","sourceType":"manual","chunks":[{"id":"indoor-air-quality_chunk_0","docId":"indoor-air-quality","docTitle":"Indoor Air Quality (IAQ) Solutions","sourceType":"manual","headingPath":["Indoor Air Quality (IAQ) Solutions","Why IAQ Matters"],"text":"The EPA estimates indoor air can be 2–5\xd7 more polluted than outdoor air. HVAC systems can improve or worsen IAQ depending on filtration, humidity control, and ventilation.","wordCount":27},{"id":"indoor-air-quality_chunk_1","docId":"indoor-air-quality","docTitle":"Indoor Air Quality (IAQ) Solutions","sourceType":"manual","headingPath":["Indoor Air Quality (IAQ) Solutions","Common IAQ Products We Install","Energy Recovery Ventilators (ERV)"],"text":"### UV Air Purifiers\\nUltraviolet-C (UV-C) light kills bacteria, mold spores, and viruses on the evaporator coil and in the airstream.\\n\\n**Installation types:**\\n- **Coil-mounted:** Single lamp pointed at evaporator coil — prevents microbial growth on coil surface\\n- **Air-handler mounted (dual lamp):** Both coil and airstream treatment\\n\\n**SKU:** MAINT-UV-SYSTEM ($595 installed)  \\n**Lamp replacement:** Annual (SKU: MAINT-UV-LAMP, $125)\\n\\n### Media Filter Cabinets\\nUpgrade from 1\\" filters to 4\\" or 5\\" media filters. MERV 11–13 captures pollen, dust mites, mold spores, and some bacteria.\\n\\n- More surface area = lower static pressure than high-MERV 1\\" filters\\n- Replace every 6–12 months (vs. monthly for 1\\" filters)\\n- Requires cabinet installation between return and air handler\\n\\n**SKU:** IAQ-MEDIA-CABINET ($445 installed)\\n\\n### Whole-Home Humidifiers\\nAustin\'s dry winters benefit from added humidity. Target range: 35–50% RH.\\n\\n**Types:**\\n- **Bypass humidifier:** Uses furnace heat + bypass duct. Lower cost, less effective.\\n- **Fan-powered humidifier:** Own motor, more consistent output. Recommended.\\n\\n**SKU:** IAQ-HUMID-WHL ($895 installed)\\n\\n### Whole-Home Dehumidifiers\\nTexas summers often exceed 60% indoor humidity, causing comfort issues and mold risk.\\n\\n**SKU:** IAQ-DEHUM ($1,895 installed)  \\n**Target:** Maintain 45–55% RH in summer\\n\\n### Energy Recovery Ventilators (ERV)\\nBrings fresh outdoor air in while recovering energy from exhaust air. Required in very tight homes under new energy codes.\\n\\n**SKU:** IAQ-ERV ($2,495 installed)","wordCount":214},{"id":"indoor-air-quality_chunk_2","docId":"indoor-air-quality","docTitle":"Indoor Air Quality (IAQ) Solutions","sourceType":"manual","headingPath":["Indoor Air Quality (IAQ) Solutions","Selling IAQ to Customers"],"text":"- Homes with allergies or asthma: lead with UV + media filter\\n- New construction (tight homes): ERV for ventilation\\n- Comfort complaints in summer: dehumidifier conversation\\n- \\"I\'m always dusting\\": HEPA or media filter upgrade","wordCount":36}],"totalChunks":3,"createdAt":"2026-10-03T15:40:24.897Z"},{"id":"maintenance-checklist","title":"Northwind Heating & Air — Maintenance Checklist","sourceType":"guide","chunks":[{"id":"maintenance-checklist_chunk_0","docId":"maintenance-checklist","docTitle":"Northwind Heating & Air — Maintenance Checklist","sourceType":"guide","headingPath":["Northwind Heating & Air — Maintenance Checklist","Annual AC Tune-Up Checklist","Documentation"],"text":"### Outdoor Unit\\n- [ ] Inspect and clean condenser coil (use approved coil cleaner + rinse)\\n- [ ] Check and clear debris from around unit (minimum 2ft clearance)\\n- [ ] Inspect fan blade for cracks, bending, or damage\\n- [ ] Lubricate fan motor bearings (if applicable — many modern motors are sealed)\\n- [ ] Inspect and tighten electrical connections\\n- [ ] Test capacitor(s) with capacitor meter — record \xb5F reading\\n- [ ] Test contactor — inspect contact points for pitting\\n- [ ] Check refrigerant pressures (record suction and discharge)\\n- [ ] Calculate superheat and subcooling\\n- [ ] Inspect service valves for leaks\\n- [ ] Check unit leveling and pad condition\\n\\n### Indoor Unit (Air Handler / Furnace)\\n- [ ] Replace or clean air filter — record size and MERV rating\\n- [ ] Inspect evaporator coil — clean if needed\\n- [ ] Inspect and flush condensate drain line\\n- [ ] Add condensate pan tablet (algaecide)\\n- [ ] Test condensate overflow float switch\\n- [ ] Inspect blower wheel for debris\\n- [ ] Measure blower motor amp draw\\n- [ ] Check all electrical connections in air handler\\n- [ ] Inspect ductwork connections at unit for leaks\\n- [ ] Test thermostat operation (heating + cooling modes)\\n- [ ] Verify temperature differential (return air vs. supply air — should be 16–22\xb0F)\\n\\n### Documentation\\n- Record all measurements on work order\\n- Note any items needing follow-up\\n- Leave copy of completed checklist with customer\\n- Photo document any concerns found","wordCount":267},{"id":"maintenance-checklist_chunk_1","docId":"maintenance-checklist","docTitle":"Northwind Heating & Air — Maintenance Checklist","sourceType":"guide","headingPath":["Northwind Heating & Air — Maintenance Checklist","Comfort Club Member Notes"],"text":"- Members receive priority scheduling and a 15% discount on repairs found during tune-up\\n- Two tune-ups per year (AC in spring, heating in fall) are included in Comfort and Premier tiers","wordCount":32}],"totalChunks":2,"createdAt":"2026-10-03T15:40:24.898Z"},{"id":"r410a-refrigerant-safety","title":"R-410A Refrigerant Safety","sourceType":"manual","chunks":[{"id":"r410a-refrigerant-safety_chunk_0","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","What is R-410A?"],"text":"R-410A (trade names: Puron, Genetron AZ-20) is a hydrofluorocarbon (HFC) refrigerant used in most residential AC systems installed after 2010. It replaced R-22 due to lower ozone depletion potential.","wordCount":29},{"id":"r410a-refrigerant-safety_chunk_1","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Regulatory Requirements"],"text":"All technicians handling refrigerants must hold an **EPA 608 certification**. Intentional venting of R-410A is a federal violation under Section 608 of the Clean Air Act, punishable by fines up to $44,539 per day per violation.","wordCount":36},{"id":"r410a-refrigerant-safety_chunk_2","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Safety Properties"],"text":"- **Boiling point:** -51.7\xb0C (-61\xb0F) at atmospheric pressure\\n- **GWP:** 2,088 (higher than R-22; phase-down scheduled under AIM Act by 2036)\\n- **Flammability:** Non-flammable (A1 classification)\\n- **Toxicity:** Low — but displaces oxygen in enclosed spaces","wordCount":36},{"id":"r410a-refrigerant-safety_chunk_3","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Handling Precautions"],"text":"1. Always work in well-ventilated areas\\n2. Wear safety glasses — liquid refrigerant can cause frostbite on contact\\n3. Never use oxygen or air to pressurize refrigerant circuits\\n4. Store cylinders upright in cool, dry location away from heat sources\\n5. R-410A cylinders are **pink** — do not confuse with other refrigerants","wordCount":52},{"id":"r410a-refrigerant-safety_chunk_4","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Operating Pressures (typical residential)"],"text":"| Condition | Suction Pressure | Discharge Pressure |\\n|-----------|-----------------|-------------------|\\n| 95\xb0F ambient, normal operation | 118–125 psi | 390–420 psi |\\n| Low charge | <110 psi | <350 psi |\\n| High charge / restriction | >135 psi | >450 psi |","wordCount":44},{"id":"r410a-refrigerant-safety_chunk_5","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Recovery Procedure"],"text":"1. Connect recovery machine to system\\n2. Recover to 0 psi or lower (pull to vacuum if possible)\\n3. Record weight of recovered refrigerant on work order\\n4. Use only certified recovery cylinders","wordCount":33}],"totalChunks":6,"createdAt":"2026-10-03T15:40:24.899Z"},{"id":"refrigerant-leak-detection","title":"Refrigerant Leak Detection","sourceType":"manual","chunks":[{"id":"refrigerant-leak-detection_chunk_0","docId":"refrigerant-leak-detection","docTitle":"Refrigerant Leak Detection","sourceType":"manual","headingPath":["Refrigerant Leak Detection","Methods of Detection","4. Ultrasonic Detector"],"text":"### 1. Electronic Leak Detector\\n**Best for:** Finding leaks quickly, especially in hard-to-see areas.\\n- Heated diode detectors respond to halogenated compounds\\n- Infrared detectors are more sensitive and have fewer false alarms\\n- Move probe slowly (~1 inch/second) around suspected areas\\n- Start at bottom of components (refrigerant vapor is heavier than air at low concentrations)\\n\\n### 2. Fluorescent Dye\\n**Best for:** Confirming leak location, recurring leaks.\\n- UV dye injected into system circulates with oil and marks leak points\\n- Use manufacturer-approved dye (avoid generic dyes in warranty equipment)\\n- Requires UV lamp for detection\\n- Record dye injection on service sticker for future techs\\n\\n### 3. Soap Bubbles\\n**Best for:** Pressurized system checks, verifying repairs.\\n- Apply nitrogen-purged system pressure before using (never pressurize with system refrigerant for leak check alone)\\n- Use approved leak detection soap — standard dish soap can be corrosive\\n- Good for accessible fittings and brazed joints\\n\\n### 4. Ultrasonic Detector\\n**Best for:** Large leaks, pressurized lines.","wordCount":165},{"id":"refrigerant-leak-detection_chunk_1","docId":"refrigerant-leak-detection","docTitle":"Refrigerant Leak Detection","sourceType":"manual","headingPath":["Refrigerant Leak Detection","Common Leak Locations (by frequency)"],"text":"1. Schrader valve cores (check first — quick fix)\\n2. Flare fittings at service valves\\n3. Brazed joints at coil connections\\n4. Evaporator coil — corrosion (formicary corrosion in copper coils)\\n5. Condenser coil — impact damage or vibration cracks","wordCount":40},{"id":"refrigerant-leak-detection_chunk_2","docId":"refrigerant-leak-detection","docTitle":"Refrigerant Leak Detection","sourceType":"manual","headingPath":["Refrigerant Leak Detection","Formicary Corrosion"],"text":"A specific problem with copper evaporator coils in newer construction:\\n- Caused by formic acid + water + oxygen reacting with copper\\n- Forms pinholes in coil walls, often undetectable visually\\n- More common with newer homes using VOC-emitting materials\\n- Solution: aluminum coils or coil coating products","wordCount":48},{"id":"refrigerant-leak-detection_chunk_3","docId":"refrigerant-leak-detection","docTitle":"Refrigerant Leak Detection","sourceType":"manual","headingPath":["Refrigerant Leak Detection","Documenting Leaks"],"text":"Always document: location found, method used, refrigerant type, amount added. Per EPA regulations, systems over 50 lbs charge must have leaks repaired within 30 days (HVACR systems) if annual leak rate exceeds 30%.","wordCount":33}],"totalChunks":4,"createdAt":"2026-10-03T15:40:24.899Z"},{"id":"seer2-ratings-explained","title":"SEER2 Ratings Explained","sourceType":"manual","chunks":[{"id":"seer2-ratings-explained_chunk_0","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","What is SEER2?"],"text":"**SEER2** (Seasonal Energy Efficiency Ratio 2) is the updated efficiency standard for residential AC and heat pump equipment, effective January 1, 2023. It replaced the original SEER rating.\\n\\nSEER2 uses a more realistic test procedure (M1 test method) that accounts for static pressure in ductwork, resulting in ratings approximately 4–7% lower than equivalent SEER equipment.","wordCount":55},{"id":"seer2-ratings-explained_chunk_1","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","Minimum Efficiency Requirements (2023+)"],"text":"| Region | Minimum SEER2 (AC) | Minimum SEER2 (Heat Pump) |\\n|--------|-------------------|--------------------------|\\n| Southeast (including Texas) | 15.2 | 15.2 |\\n| Southwest | 15.2 | 15.2 |\\n| North | 13.4 | 14.3 |\\n\\nTexas falls in the **Southeast/Southwest** region — minimum is **15.2 SEER2**.","wordCount":47},{"id":"seer2-ratings-explained_chunk_2","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","SEER2 to Energy Savings"],"text":"| SEER2 Rating | Annual Estimated Savings vs. 10 SEER |\\n|-------------|--------------------------------------|\\n| 14 SEER2 | ~29% energy reduction |\\n| 16 SEER2 | ~38% energy reduction |\\n| 18 SEER2 | ~44% energy reduction |\\n| 20 SEER2 | ~50% energy reduction |\\n\\n*Based on average Austin TX usage (2,000+ cooling hours/year)*","wordCount":53},{"id":"seer2-ratings-explained_chunk_3","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","SEER vs SEER2 Conversion (Approximate)"],"text":"Multiply SEER by 0.95 to estimate the SEER2 equivalent:\\n- 16 SEER ≈ 15.2 SEER2\\n- 18 SEER ≈ 17.1 SEER2\\n- 20 SEER ≈ 19.0 SEER2","wordCount":27},{"id":"seer2-ratings-explained_chunk_4","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","Communicating Value to Customers"],"text":"- A 16-year-old 10 SEER unit replaced with a 16 SEER2 unit cuts cooling costs by ~38%\\n- In Austin\'s climate, a typical home saves $300–600/year in cooling costs\\n- Most new equipment qualifies for the **25C federal tax credit** (up to $600 for heat pumps and AC meeting efficiency thresholds)","wordCount":51}],"totalChunks":5,"createdAt":"2026-10-03T15:40:24.899Z"},{"id":"thermostat-wiring-guide","title":"Thermostat Wiring Guide","sourceType":"guide","chunks":[{"id":"thermostat-wiring-guide_chunk_0","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Standard Wire Color Codes"],"text":"| Wire Color | Terminal | Function |\\n|-----------|----------|----------|\\n| Red | R or Rh/Rc | 24V power from transformer |\\n| Green | G | Fan (indoor blower) |\\n| Yellow | Y | Compressor / cooling |\\n| White | W | Heat (gas valve or aux heat) |\\n| Blue or Black | C | Common (24V return) |\\n| Orange | O | Reversing valve (heat pumps — energized in cooling) |\\n| Dark Blue | B | Reversing valve (Carrier/Bryant — energized in heating) |","wordCount":90},{"id":"thermostat-wiring-guide_chunk_1","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Common Configurations","Heat Pump (7-wire)"],"text":"### Standard AC + Gas Furnace (5-wire)\\n```\\nR — Rh (or R)\\nG — G\\nY — Y\\nW — W\\nC — C\\n```\\n\\n### Heat Pump (7-wire)\\n```\\nR — R\\nG — G\\nY — Y\\nO — O (or B for Carrier)\\nW — W (aux heat)\\nC — C\\nE — E (emergency heat)\\n```","wordCount":61},{"id":"thermostat-wiring-guide_chunk_2","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Troubleshooting"],"text":"| Symptom | Likely Wiring Cause |\\n|---------|-------------------|\\n| Fan runs but no cooling | Y wire loose or open |\\n| Cooling but fan won\'t turn off | G wire shorted to R |\\n| No heat, no cooling | R wire open or blown fuse |\\n| Heat pump blows cold in heat mode | O/B wire reversed or missing |\\n| Short cycling | C wire missing (wifi thermostat drawing power from Y) |","wordCount":77},{"id":"thermostat-wiring-guide_chunk_3","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Installing a Smart Thermostat Without C-Wire"],"text":"Many smart thermostats (Nest, Ecobee) require a C wire for continuous 24V power. Options when no C wire exists:\\n1. **Run a new wire** — best solution if accessible\\n2. **Use a C-wire adapter** (some brands include one)\\n3. **Use the G terminal** as C and enable \\"fan always on\\" mode (not recommended for most customers)\\n4. **Install a 24V plug-in transformer** at the air handler","wordCount":66},{"id":"thermostat-wiring-guide_chunk_4","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Important Notes"],"text":"- Always disconnect power at disconnect box before working on wiring\\n- Rh and Rc are separate terminals on some thermostats — jumper them if the system has a single R wire\\n- Never connect 24V control wires to line voltage (120V/240V) terminals","wordCount":43}],"totalChunks":5,"createdAt":"2026-10-03T15:40:24.900Z"},{"id":"warranty-terms","title":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","chunks":[{"id":"warranty-terms_chunk_0","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","Labor Warranty"],"text":"All repair work performed by Northwind technicians carries a **90-day labor warranty** from the date of service. If the same failure recurs within 90 days, we return at no additional labor charge.\\n\\n**Exclusions:**\\n- Failures caused by misuse, neglect, or unauthorized repairs\\n- Failures caused by electrical surges or water damage\\n- Filter changes and routine consumables","wordCount":57},{"id":"warranty-terms_chunk_1","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","Parts Warranty"],"text":"Parts installed by Northwind are covered by the manufacturer\'s warranty, passed through to the customer. Common terms:\\n\\n| Part Type | Typical Warranty |\\n|----------|-----------------|\\n| Compressor | 5–10 years (registered) |\\n| Capacitor | 1 year manufacturer |\\n| Contactor | 1 year manufacturer |\\n| Control board | 5 years (varies by brand) |\\n| Motors (blower, fan) | 5 years (varies) |","wordCount":65},{"id":"warranty-terms_chunk_2","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","Equipment Warranty (New Installs)","Northwind Install Labor Warranty"],"text":"### Carrier Equipment (registered within 90 days of install)\\n- **Compressor:** 10 years\\n- **All other covered components:** 10 years\\n- **Heat exchanger (furnace):** Lifetime\\n\\n**Important:** Registration must be completed at [carrier.com](https://carrier.com/residential/en/us/register-my-product/) within 90 days of installation. Unregistered units revert to 5-year parts warranty.\\n\\n### Northwind Install Labor Warranty\\n- 1 year on installation labor for new equipment","wordCount":58},{"id":"warranty-terms_chunk_3","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","How to File a Warranty Claim"],"text":"1. Call Northwind at 555-0100 or use the customer portal\\n2. Provide: original invoice number, model, serial number, description of issue\\n3. We will assess warranty eligibility and schedule service\\n4. Manufacturer warranty claims require proof of original installation date","wordCount":40},{"id":"warranty-terms_chunk_4","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","Out-of-Warranty Equipment"],"text":"For equipment older than 10 years with significant repair costs, we recommend requesting a replacement estimate. Units older than 12 years rarely justify major repairs economically.","wordCount":26}],"totalChunks":5,"createdAt":"2026-10-03T15:40:24.900Z"}],"chunks":[{"id":"air-handler-maintenance_chunk_0","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Overview"],"text":"The air handler (or fan coil) circulates conditioned air through the home. Regular maintenance prevents efficiency loss, water damage, and early equipment failure.","wordCount":23},{"id":"air-handler-maintenance_chunk_1","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Blower Assembly","Blower Motor"],"text":"### Blower Wheel Cleaning\\nA dirty blower wheel loses up to 30% efficiency. Signs: reduced airflow, higher energy bills.\\n\\n**Procedure:**\\n1. Disconnect power at disconnect and breaker\\n2. Remove blower compartment door\\n3. Slide out blower assembly (note wire routing)\\n4. Clean wheel with stiff brush and coil cleaner\\n5. Rinse with water, allow to dry completely before reinstalling\\n6. Check wheel balance — replace if bent or cracked\\n\\n### Blower Motor\\n- **PSC motors:** Lubricate oil ports with 3-in-1 or SAE 20 non-detergent oil (2–3 drops each port) if not factory-sealed\\n- **ECM (variable speed) motors:** Factory sealed, no lubrication needed\\n- Check run capacitor for PSC motors — most air handler motor failures start with a failed capacitor\\n\\n**Normal amp draw:** Should be within 10% of nameplate FLA","wordCount":130},{"id":"air-handler-maintenance_chunk_2","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Evaporator Coil","Inspecting for Leaks"],"text":"### Cleaning\\n- Access panel removal required — coil cleaning is more involved than condenser\\n- Apply no-rinse evaporator coil cleaner; allow to drain through condensate system\\n- Never use acidic cleaners on aluminum coils\\n\\n### Inspecting for Leaks\\n- Look for oil staining around coil connections\\n- Check for low refrigerant symptoms (low suction pressure, high superheat)\\n- Formicary corrosion: small pinholes, hard to detect — consider dye if recurring low charge","wordCount":73},{"id":"air-handler-maintenance_chunk_3","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Condensate System","Common Clog Locations"],"text":"### Drain Line Maintenance\\n- Flush annually with condensate cleaner or 50/50 bleach/water\\n- Install condensate pan tablets (algaecide) to prevent buildup\\n- Verify float switch operation — should cut unit off if pan fills\\n\\n### Common Clog Locations\\n1. At the P-trap (if installed)\\n2. At the PVC elbow near the unit\\n3. Where drain exits to exterior (check for wasp nests or debris)","wordCount":65},{"id":"air-handler-maintenance_chunk_4","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Filter Slot Inspection"],"text":"- Verify filter fits snugly — air bypassing filter goes straight to blower wheel and coil\\n- Check for damaged filter frame or bypass gaps\\n- Consider upgrading to media cabinet for high-MERV filtration without pressure drop","wordCount":37},{"id":"air-handler-maintenance_chunk_5","docId":"air-handler-maintenance","docTitle":"Air Handler Maintenance Guide","sourceType":"manual","headingPath":["Air Handler Maintenance Guide","Electrical Connections"],"text":"- Tighten all wire terminals in unit disconnect and air handler control box\\n- Check for signs of overheating at wire connections (discoloration, melted insulation)\\n- Verify 24V transformer output: should measure 24–28V AC","wordCount":34},{"id":"capacitor-sizing-guide_chunk_0","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Overview"],"text":"Run capacitors store electrical energy and provide the phase shift needed to start and run single-phase AC motors. Selecting the correct capacitor is critical — an under- or over-rated capacitor causes motor failure.","wordCount":33},{"id":"capacitor-sizing-guide_chunk_1","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Reading the Nameplate"],"text":"Every capacitor is rated in microfarads (\xb5F) and volts. The rating is printed on the side:\\n- **Dual run capacitor:** Two ratings separated by a slash (e.g., `45/5 \xb5F, 440V`). The higher value runs the compressor; the lower value runs the condenser fan motor.\\n- **Single run capacitor:** One rating (e.g., `35 \xb5F, 370V`).","wordCount":54},{"id":"capacitor-sizing-guide_chunk_2","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Common Carrier Unit Ratings"],"text":"| Model | Compressor Cap (\xb5F) | Fan Cap (\xb5F) | Voltage |\\n|-------|--------------------|-----------|----|\\n| 24ACC624A003 | 40 | 5 | 440V |\\n| 24ACC636A003 | 45 | 5 | 440V |\\n| 24ACC648A003 | 50 | 5 | 440V |\\n| 24ACC660A003 | 55 | 7.5 | 440V |\\n| 24ABB336A003 | 35 | 5 | 370V |","wordCount":59},{"id":"capacitor-sizing-guide_chunk_3","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Tolerance Rules"],"text":"Capacitors are rated with a \xb16% tolerance. A capacitor measuring outside 10% of nameplate value should be replaced. Test with a capacitor meter — **never test capacitors with a standard multimeter**.","wordCount":31},{"id":"capacitor-sizing-guide_chunk_4","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Voltage Ratings"],"text":"A 440V capacitor can safely replace a 370V in the same circuit. Never install a lower voltage rating than specified.","wordCount":20},{"id":"capacitor-sizing-guide_chunk_5","docId":"capacitor-sizing-guide","docTitle":"Capacitor Sizing Guide","sourceType":"guide","headingPath":["Capacitor Sizing Guide","Failure Signs"],"text":"- Bulging or swollen top — definitive failure\\n- Capacitance reading >10% below nameplate\\n- Burn marks or physical damage\\n- Unit runs but draws high amperage","wordCount":27},{"id":"common-ac-error-codes_chunk_0","docId":"common-ac-error-codes","docTitle":"Common AC Error Codes","sourceType":"manual","headingPath":["Common AC Error Codes","Carrier ComfortLink II Error Codes"],"text":"| Code | Description | Likely Cause | Action |\\n|------|-------------|-------------|--------|\\n| E1 | Indoor/outdoor communication fault | Wiring issue, board failure | Check communication wiring between indoor and outdoor units |\\n| E2 | Indoor unit thermistor fault | Thermistor open or shorted | Test thermistor resistance; replace if out of spec |\\n| E3 | Outdoor unit high pressure fault | Overcharge, dirty coil, failed fan | Check refrigerant charge, clean coil, verify fan operation |\\n| E4 | Outdoor unit low pressure fault | Undercharge, leak, restricted filter drier | Check charge, inspect for leaks, replace drier |\\n| E5 | Compressor high temperature | Low airflow, overcharge, dirty coil | Inspect airflow, check refrigerant, clean coil |\\n| E6 | Communication error indoor/outdoor | Control board fault | Power cycle; replace board if persistent |\\n| E8 | Indoor overflow switch open | Clogged drain, stuck float | Clear drain, clean pan, verify float switch |","wordCount":160},{"id":"common-ac-error-codes_chunk_1","docId":"common-ac-error-codes","docTitle":"Common AC Error Codes","sourceType":"manual","headingPath":["Common AC Error Codes","Trane XR Series Error Codes (flash codes)"],"text":"| Flashes | Description |\\n|---------|-------------|\\n| 2 | High pressure lockout |\\n| 3 | Low pressure lockout |\\n| 4 | Open high pressure switch |\\n| 5 | Open low pressure switch |\\n| 6 | Compressor fault |\\n| 7 | Outdoor fan fault |","wordCount":49},{"id":"common-ac-error-codes_chunk_2","docId":"common-ac-error-codes","docTitle":"Common AC Error Codes","sourceType":"manual","headingPath":["Common AC Error Codes","Goodman / Amana LED Flash Codes"],"text":"| LED Pattern | Description |\\n|-------------|-------------|\\n| 1 flash | Normal operation |\\n| 2 flashes | High pressure fault |\\n| 3 flashes | Low pressure fault |\\n| 4 flashes | Open circuit (thermistor or board) |\\n| 5 flashes | Condensate overflow |\\n| Continuous | Check thermostat signal |","wordCount":54},{"id":"common-ac-error-codes_chunk_3","docId":"common-ac-error-codes","docTitle":"Common AC Error Codes","sourceType":"manual","headingPath":["Common AC Error Codes","General Troubleshooting Notes"],"text":"- Always note error codes before power cycling — some codes clear on reset\\n- Document codes on the job work order for warranty purposes\\n- Repeated E3/E4 codes after clearing usually indicate refrigerant system issues, not electrical","wordCount":38},{"id":"company-policies_chunk_0","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Service Area"],"text":"Austin metro area including: Austin, Round Rock, Cedar Park, Pflugerville, Georgetown, Kyle, Buda, and Manor. Standard service up to 40 miles from our shop at 2400 S Lamar Blvd.","wordCount":29},{"id":"company-policies_chunk_1","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Hours of Operation"],"text":"- **Standard service:** Monday–Saturday, 7:00 AM – 7:00 PM\\n- **Emergency service:** 24 hours/day, 7 days/week (answered by Ava, dispatched to on-call tech)\\n- **Office/phone:** Monday–Friday, 8:00 AM – 6:00 PM","wordCount":31},{"id":"company-policies_chunk_2","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Pricing Policy"],"text":"- All pricing is from the approved price book — technicians may not quote custom prices\\n- Diagnostic / service call fee: $89 (applied toward repair if customer proceeds)\\n- Emergency after-hours call fee: $195 (in addition to repair costs)\\n- All prices include standard labor; unusual access situations may require supervisor approval for premium","wordCount":55},{"id":"company-policies_chunk_3","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Approval Thresholds"],"text":"| Amount | Approval Required |\\n|--------|-----------------|\\n| Up to $499 | Tech authorized to proceed with customer approval |\\n| $500–$4,999 | Customer signature on estimate required |\\n| $5,000+ | Owner (Maria Lopez) approval required before presenting to customer |\\n| Refunds >$100 | Owner approval required |\\n| Discounts >10% | Owner approval required |","wordCount":58},{"id":"company-policies_chunk_4","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Comfort Club Membership Plans"],"text":"| Tier | Monthly Rate | Included | Discount on Repairs |\\n|------|-------------|---------|-------------------|\\n| Basic | $12.99 | 1 tune-up/year | 10% |\\n| Comfort | $19.99 | 2 tune-ups/year | 15% |\\n| Premier | $29.99 | 2 tune-ups + priority + free service call | 20% |\\n\\nMembers get priority scheduling — their jobs are booked before non-member same-day requests.","wordCount":62},{"id":"company-policies_chunk_5","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Customer Communication Standards"],"text":"- All customers receive a text/email confirmation within 5 minutes of booking\\n- Tech sends \\"on my way\\" notification when departing for job\\n- All calls are answered within 3 rings (by Ava, 24/7)\\n- Complaints escalated to dispatcher within 1 business day","wordCount":43},{"id":"company-policies_chunk_6","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Technician Conduct"],"text":"- Wear Northwind uniform and shoe covers in customer homes\\n- Present good/better/best estimate — never pressure customers\\n- Never discuss competitor pricing or criticize competitor work\\n- If a job scope exceeds tech\'s certification, call dispatcher before proceeding\\n- All findings must be documented with photos in the job work order","wordCount":52},{"id":"company-policies_chunk_7","docId":"company-policies","docTitle":"Northwind Heating & Air — Company Policies","sourceType":"policy","headingPath":["Northwind Heating & Air — Company Policies","Warranty Claims"],"text":"See warranty-terms.md for full warranty policy.\\n- Labor warranty: 90 days on all repair work\\n- Parts warranty: Pass-through of manufacturer warranty\\n- New equipment: 10-year parts (registered) / 1-year labor","wordCount":31},{"id":"compressor-diagnosis_chunk_0","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","Overview"],"text":"The compressor is the heart of the refrigeration cycle — and the most expensive component to replace. Accurate diagnosis before condemning a compressor saves customers thousands of dollars.","wordCount":28},{"id":"compressor-diagnosis_chunk_1","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","Electrical Tests","Amperage Test (compressor running)"],"text":"### Resistance Test (compressor off, disconnected)\\nMeasure resistance between terminals C, R, and S:\\n- C–R (common to run): typically 2–8 Ω\\n- C–S (common to start): typically 3–12 Ω  \\n- R–S (run to start): should equal C–R + C–S\\n\\n**Failed if:** Any reading is open (OL) or shorted to ground (test each terminal to chassis ground — should be OL).\\n\\n### Amperage Test (compressor running)\\nCompare measured amps to nameplate RLA (Rated Load Amps):\\n- Within 10% of RLA: normal\\n- >115% of RLA: overloaded — check for high head pressure, low charge, or mechanical issue\\n- <50% of RLA with no cooling: possible open winding or valve failure","wordCount":110},{"id":"compressor-diagnosis_chunk_2","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","Mechanical Tests","Locked Rotor"],"text":"### Compressor Valve Test\\nIf suction pressure rises when compressor shuts off (equalization test):\\n1. Let system run 15 minutes\\n2. Shut off compressor (disconnect Y wire)\\n3. Watch suction pressure — should hold or rise slowly\\n4. **If suction rises to discharge level within 60 seconds:** compressor valves are failed\\n\\n### Locked Rotor\\n- Compressor hums but won\'t start, trips on thermal overload\\n- May indicate: failed start capacitor, failed run capacitor, failed start relay, or mechanical lock\\n- Test capacitors first (fastest fix)\\n- Hard start kit can help marginal compressors","wordCount":93},{"id":"compressor-diagnosis_chunk_3","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","Oil Failures"],"text":"- **Slugging (liquid refrigerant in oil):** Loud banging on startup, especially after long off cycle. Crankcase heater prevents this.\\n- **Oil loss:** Often caused by refrigerant migration — compressor overheats, wears rapidly","wordCount":32},{"id":"compressor-diagnosis_chunk_4","docId":"compressor-diagnosis","docTitle":"Compressor Diagnosis","sourceType":"manual","headingPath":["Compressor Diagnosis","When to Replace vs. Repair"],"text":"- Compressor ≤5 years: attempt repair if electrical (capacitor, contactor)\\n- Compressor 6–10 years with catastrophic failure: get second opinion on replacement vs. repair\\n- Compressor >10 years: recommend full system replacement — compressor replacement alone rarely cost-effective\\n- **Never replace compressor without finding and fixing root cause of failure**","wordCount":50},{"id":"ductwork-inspection_chunk_0","docId":"ductwork-inspection","docTitle":"Ductwork Inspection Checklist","sourceType":"manual","headingPath":["Ductwork Inspection Checklist","Visual Inspection Points","Common Problem Areas"],"text":"### Supply Ductwork\\n- Check all duct connections at air handler for gaps or separation\\n- Inspect flex duct for kinks, tears, or disconnected sections\\n- Verify all supply registers are open and unobstructed\\n- Check insulation on supply ducts in unconditioned spaces (attics, crawl spaces) — should be R-8 minimum in Texas\\n\\n### Return Ductwork\\n- Inspect return grille filter for blockage\\n- Check return plenum for air leaks (can cause attic air infiltration)\\n- Verify adequate return air path in all rooms (undercut doors or transfer grilles)\\n\\n### Common Problem Areas\\n1. **Flex duct in attics:** Often kinked, over-extended, or disconnected at boots\\n2. **Main trunk connections:** Sheet metal screws missing, tape failing\\n3. **Boot-to-floor connections:** Often unsealed, causing conditioned air to enter under-floor spaces\\n4. **Air handler connections:** Should be sealed with mastic, not just tape","wordCount":139},{"id":"ductwork-inspection_chunk_1","docId":"ductwork-inspection","docTitle":"Ductwork Inspection Checklist","sourceType":"manual","headingPath":["Ductwork Inspection Checklist","Duct Leakage Testing"],"text":"A blower door test or duct blaster test measures duct leakage. Texas standards:\\n- New construction: <4% total leakage at 25 Pa\\n- Existing systems: No formal standard, but >25% leakage warrants attention","wordCount":33},{"id":"ductwork-inspection_chunk_2","docId":"ductwork-inspection","docTitle":"Ductwork Inspection Checklist","sourceType":"manual","headingPath":["Ductwork Inspection Checklist","Sealing Materials"],"text":"- **Mastic sealant:** Best for rigid sheet metal connections — durable, flexible\\n- **Foil tape (UL-listed):** Acceptable for small gaps, not for large leaks\\n- **Avoid:** Standard cloth duct tape — fails within 1–2 years","wordCount":35},{"id":"ductwork-inspection_chunk_3","docId":"ductwork-inspection","docTitle":"Ductwork Inspection Checklist","sourceType":"manual","headingPath":["Ductwork Inspection Checklist","Duct Sizing Notes"],"text":"Undersized ductwork is a common cause of comfort complaints. As a rule of thumb:\\n- Each 100 CFM requires approximately 1 sq inch of duct area\\n- 8\\" round duct carries ~200 CFM at 0.08\\" WC static pressure\\n- Consult Manual D for accurate sizing calculations","wordCount":46},{"id":"emergency-procedures_chunk_0","docId":"emergency-procedures","docTitle":"Emergency Procedures","sourceType":"guide","headingPath":["Emergency Procedures","Gas Smell (Suspected Leak)"],"text":"**Immediate actions:**\\n1. Do NOT operate any electrical switches, light switches, or appliances\\n2. Do NOT use your phone inside the building\\n3. Evacuate the building immediately\\n4. Leave the door open as you exit\\n5. Once outside and at a safe distance, call 911 and your gas provider\\n6. Do NOT return to the building until cleared by emergency responders\\n\\n**Northwind policy:** Any call involving gas smell is immediately transferred to our on-call emergency team. We do not attempt to diagnose or schedule over the phone — the customer is directed to evacuate immediately.","wordCount":95},{"id":"emergency-procedures_chunk_1","docId":"emergency-procedures","docTitle":"Emergency Procedures","sourceType":"guide","headingPath":["Emergency Procedures","Carbon Monoxide (CO) Alert"],"text":"Signs of CO: headache, dizziness, nausea, confusion (symptoms improve when leaving the building).\\n\\n1. Evacuate immediately — leave doors open\\n2. Call 911\\n3. Do not re-enter until cleared by fire department\\n4. Northwind emergency team responds within 2 hours for CO-related service calls\\n\\n**CO sources in HVAC:** Cracked heat exchanger, backdrafting furnace, blocked flue, carbon buildup in combustion chamber.","wordCount":60},{"id":"emergency-procedures_chunk_2","docId":"emergency-procedures","docTitle":"Emergency Procedures","sourceType":"guide","headingPath":["Emergency Procedures","No Heat with Vulnerable Occupants"],"text":"When a customer reports no heat and mentions elderly occupants, infants, or people with medical conditions, Northwind treats this as an emergency call:\\n- Same-day service guaranteed (or we coordinate a temporary heater delivery)\\n- Priority tech dispatched regardless of current schedule","wordCount":42},{"id":"emergency-procedures_chunk_3","docId":"emergency-procedures","docTitle":"Emergency Procedures","sourceType":"guide","headingPath":["Emergency Procedures","Electrical Emergency at Unit"],"text":"If a customer reports sparks, burning smell, or smoke from HVAC equipment:\\n1. Advise them to cut power at the disconnect box or main breaker\\n2. Do NOT attempt to operate or reset the equipment\\n3. Schedule an emergency visit\\n\\n**Technician safety:** Before working on any system reporting electrical issues, verify power is off at both the unit disconnect AND the main panel. Test for voltage with a non-contact tester.","wordCount":70},{"id":"furnace-igniter-replacement_chunk_0","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Types of Igniters","Spark Igniter"],"text":"### Hot Surface Igniter (HSI)\\nThe most common type in modern gas furnaces. A silicon nitride or silicon carbide element heats to ~1800\xb0F when energized, igniting the gas burner.\\n\\n- **Silicon carbide:** Older, more brittle, turns orange-red when working. Resistance: 40–70 Ω when cold.\\n- **Silicon nitride:** Newer, more durable, glows yellow-white. Resistance: 15–50 Ω when cold.\\n\\n### Spark Igniter\\nUsed in some older units. Creates a spark arc to ignite the burner. Look for cracked porcelain or carbon tracking as failure indicators.","wordCount":83},{"id":"furnace-igniter-replacement_chunk_1","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Diagnostic Steps"],"text":"1. Set thermostat to Heat, observe igniter through inspection port\\n2. Igniter should glow within 30–45 seconds of call for heat\\n3. If no glow: measure 120V at igniter leads (verify voltage present)\\n4. If voltage present, no glow: igniter is open — replace\\n5. Measure resistance: out-of-spec reading indicates impending failure","wordCount":52},{"id":"furnace-igniter-replacement_chunk_2","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Resistance Quick Reference"],"text":"| Igniter Type | Good Range | Replace If |\\n|-------------|-----------|-----------|\\n| Silicon carbide | 40–70 Ω | >100 Ω or open circuit |\\n| Silicon nitride | 15–50 Ω | >60 Ω or open circuit |","wordCount":37},{"id":"furnace-igniter-replacement_chunk_3","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Replacement Procedure"],"text":"1. **Disconnect power** — 120V can cause serious injury\\n2. Turn off gas supply at unit shutoff\\n3. Remove burner compartment door\\n4. Unplug igniter harness connector\\n5. Remove mounting screw (usually M4 or 6-32 screw)\\n6. Handle new igniter by the harness only — oils from skin reduce lifespan\\n7. Install new igniter, restore connections\\n8. Test: call for heat, verify ignition within 2 ignition cycles","wordCount":67},{"id":"furnace-igniter-replacement_chunk_4","docId":"furnace-igniter-replacement","docTitle":"Furnace Igniter Replacement","sourceType":"manual","headingPath":["Furnace Igniter Replacement","Common Brands by Unit"],"text":"- Carrier/Bryant/Payne: HSI, silicon nitride, part 33331012000\\n- Trane/American Standard: HSI, silicon nitride, various by model\\n- Lennox: HSI, silicon carbide (older) or nitride (post-2010)\\n- Goodman/Amana: HSI, silicon nitride, part B1401015S","wordCount":32},{"id":"heat-pump-defrost-cycle_chunk_0","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","Why Defrost is Necessary"],"text":"In heating mode, the outdoor coil acts as the evaporator and absorbs heat from outdoor air. When outdoor temperatures fall below ~40\xb0F, moisture in the air freezes on the coil, reducing airflow and efficiency. The defrost cycle reverses this by temporarily switching the unit to cooling mode, using hot refrigerant to melt the ice.","wordCount":54},{"id":"heat-pump-defrost-cycle_chunk_1","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","How the Defrost Cycle Works"],"text":"1. Unit is in heating mode\\n2. Defrost board monitors outdoor coil temperature via thermistor\\n3. When coil temp drops below threshold (typically 26\xb0F) AND timer condition is met, defrost initiates\\n4. Reversing valve switches to cooling mode\\n5. Outdoor fan stops (prevents cold air from slowing defrost)\\n6. Indoor auxiliary heat may energize to compensate for temporary cooling effect\\n7. Defrost terminates when: coil reaches ~57\xb0F, OR 10-minute timeout reached\\n8. Unit returns to heating mode","wordCount":77},{"id":"heat-pump-defrost-cycle_chunk_2","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","Defrost Board Operation"],"text":"Most residential heat pumps use a demand defrost board (vs. time-only boards). Demand boards compare:\\n- **Outdoor coil temperature** (via coil thermistor)\\n- **Outdoor ambient temperature** (via ambient thermistor)\\n- **Timer setting** (5, 30, 60, 90 minutes between defrost checks)","wordCount":40},{"id":"heat-pump-defrost-cycle_chunk_3","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","Troubleshooting Defrost Problems"],"text":"| Symptom | Possible Cause | Check |\\n|---------|---------------|-------|\\n| Unit always in defrost | Short in coil thermistor | Test thermistor resistance |\\n| Unit never defrosts | Open coil thermistor, board fault | Test thermistor, check 24V to board |\\n| Partial defrost (ice remains) | Low charge, dirty coil, fan issue | Check charge, clean coil, verify fan |\\n| Indoor blows cold during defrost | Missing aux heat signal | Check aux heat operation |","wordCount":79},{"id":"heat-pump-defrost-cycle_chunk_4","docId":"heat-pump-defrost-cycle","docTitle":"Heat Pump Defrost Cycle","sourceType":"manual","headingPath":["Heat Pump Defrost Cycle","Thermistor Resistance (typical)"],"text":"| Temperature | Resistance |\\n|------------|-----------|\\n| 30\xb0F | ~16,000 Ω |\\n| 40\xb0F | ~12,000 Ω |\\n| 57\xb0F | ~7,500 Ω |\\n\\nReplace thermistor if resistance is open or significantly out of range.","wordCount":35},{"id":"indoor-air-quality_chunk_0","docId":"indoor-air-quality","docTitle":"Indoor Air Quality (IAQ) Solutions","sourceType":"manual","headingPath":["Indoor Air Quality (IAQ) Solutions","Why IAQ Matters"],"text":"The EPA estimates indoor air can be 2–5\xd7 more polluted than outdoor air. HVAC systems can improve or worsen IAQ depending on filtration, humidity control, and ventilation.","wordCount":27},{"id":"indoor-air-quality_chunk_1","docId":"indoor-air-quality","docTitle":"Indoor Air Quality (IAQ) Solutions","sourceType":"manual","headingPath":["Indoor Air Quality (IAQ) Solutions","Common IAQ Products We Install","Energy Recovery Ventilators (ERV)"],"text":"### UV Air Purifiers\\nUltraviolet-C (UV-C) light kills bacteria, mold spores, and viruses on the evaporator coil and in the airstream.\\n\\n**Installation types:**\\n- **Coil-mounted:** Single lamp pointed at evaporator coil — prevents microbial growth on coil surface\\n- **Air-handler mounted (dual lamp):** Both coil and airstream treatment\\n\\n**SKU:** MAINT-UV-SYSTEM ($595 installed)  \\n**Lamp replacement:** Annual (SKU: MAINT-UV-LAMP, $125)\\n\\n### Media Filter Cabinets\\nUpgrade from 1\\" filters to 4\\" or 5\\" media filters. MERV 11–13 captures pollen, dust mites, mold spores, and some bacteria.\\n\\n- More surface area = lower static pressure than high-MERV 1\\" filters\\n- Replace every 6–12 months (vs. monthly for 1\\" filters)\\n- Requires cabinet installation between return and air handler\\n\\n**SKU:** IAQ-MEDIA-CABINET ($445 installed)\\n\\n### Whole-Home Humidifiers\\nAustin\'s dry winters benefit from added humidity. Target range: 35–50% RH.\\n\\n**Types:**\\n- **Bypass humidifier:** Uses furnace heat + bypass duct. Lower cost, less effective.\\n- **Fan-powered humidifier:** Own motor, more consistent output. Recommended.\\n\\n**SKU:** IAQ-HUMID-WHL ($895 installed)\\n\\n### Whole-Home Dehumidifiers\\nTexas summers often exceed 60% indoor humidity, causing comfort issues and mold risk.\\n\\n**SKU:** IAQ-DEHUM ($1,895 installed)  \\n**Target:** Maintain 45–55% RH in summer\\n\\n### Energy Recovery Ventilators (ERV)\\nBrings fresh outdoor air in while recovering energy from exhaust air. Required in very tight homes under new energy codes.\\n\\n**SKU:** IAQ-ERV ($2,495 installed)","wordCount":214},{"id":"indoor-air-quality_chunk_2","docId":"indoor-air-quality","docTitle":"Indoor Air Quality (IAQ) Solutions","sourceType":"manual","headingPath":["Indoor Air Quality (IAQ) Solutions","Selling IAQ to Customers"],"text":"- Homes with allergies or asthma: lead with UV + media filter\\n- New construction (tight homes): ERV for ventilation\\n- Comfort complaints in summer: dehumidifier conversation\\n- \\"I\'m always dusting\\": HEPA or media filter upgrade","wordCount":36},{"id":"maintenance-checklist_chunk_0","docId":"maintenance-checklist","docTitle":"Northwind Heating & Air — Maintenance Checklist","sourceType":"guide","headingPath":["Northwind Heating & Air — Maintenance Checklist","Annual AC Tune-Up Checklist","Documentation"],"text":"### Outdoor Unit\\n- [ ] Inspect and clean condenser coil (use approved coil cleaner + rinse)\\n- [ ] Check and clear debris from around unit (minimum 2ft clearance)\\n- [ ] Inspect fan blade for cracks, bending, or damage\\n- [ ] Lubricate fan motor bearings (if applicable — many modern motors are sealed)\\n- [ ] Inspect and tighten electrical connections\\n- [ ] Test capacitor(s) with capacitor meter — record \xb5F reading\\n- [ ] Test contactor — inspect contact points for pitting\\n- [ ] Check refrigerant pressures (record suction and discharge)\\n- [ ] Calculate superheat and subcooling\\n- [ ] Inspect service valves for leaks\\n- [ ] Check unit leveling and pad condition\\n\\n### Indoor Unit (Air Handler / Furnace)\\n- [ ] Replace or clean air filter — record size and MERV rating\\n- [ ] Inspect evaporator coil — clean if needed\\n- [ ] Inspect and flush condensate drain line\\n- [ ] Add condensate pan tablet (algaecide)\\n- [ ] Test condensate overflow float switch\\n- [ ] Inspect blower wheel for debris\\n- [ ] Measure blower motor amp draw\\n- [ ] Check all electrical connections in air handler\\n- [ ] Inspect ductwork connections at unit for leaks\\n- [ ] Test thermostat operation (heating + cooling modes)\\n- [ ] Verify temperature differential (return air vs. supply air — should be 16–22\xb0F)\\n\\n### Documentation\\n- Record all measurements on work order\\n- Note any items needing follow-up\\n- Leave copy of completed checklist with customer\\n- Photo document any concerns found","wordCount":267},{"id":"maintenance-checklist_chunk_1","docId":"maintenance-checklist","docTitle":"Northwind Heating & Air — Maintenance Checklist","sourceType":"guide","headingPath":["Northwind Heating & Air — Maintenance Checklist","Comfort Club Member Notes"],"text":"- Members receive priority scheduling and a 15% discount on repairs found during tune-up\\n- Two tune-ups per year (AC in spring, heating in fall) are included in Comfort and Premier tiers","wordCount":32},{"id":"r410a-refrigerant-safety_chunk_0","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","What is R-410A?"],"text":"R-410A (trade names: Puron, Genetron AZ-20) is a hydrofluorocarbon (HFC) refrigerant used in most residential AC systems installed after 2010. It replaced R-22 due to lower ozone depletion potential.","wordCount":29},{"id":"r410a-refrigerant-safety_chunk_1","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Regulatory Requirements"],"text":"All technicians handling refrigerants must hold an **EPA 608 certification**. Intentional venting of R-410A is a federal violation under Section 608 of the Clean Air Act, punishable by fines up to $44,539 per day per violation.","wordCount":36},{"id":"r410a-refrigerant-safety_chunk_2","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Safety Properties"],"text":"- **Boiling point:** -51.7\xb0C (-61\xb0F) at atmospheric pressure\\n- **GWP:** 2,088 (higher than R-22; phase-down scheduled under AIM Act by 2036)\\n- **Flammability:** Non-flammable (A1 classification)\\n- **Toxicity:** Low — but displaces oxygen in enclosed spaces","wordCount":36},{"id":"r410a-refrigerant-safety_chunk_3","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Handling Precautions"],"text":"1. Always work in well-ventilated areas\\n2. Wear safety glasses — liquid refrigerant can cause frostbite on contact\\n3. Never use oxygen or air to pressurize refrigerant circuits\\n4. Store cylinders upright in cool, dry location away from heat sources\\n5. R-410A cylinders are **pink** — do not confuse with other refrigerants","wordCount":52},{"id":"r410a-refrigerant-safety_chunk_4","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Operating Pressures (typical residential)"],"text":"| Condition | Suction Pressure | Discharge Pressure |\\n|-----------|-----------------|-------------------|\\n| 95\xb0F ambient, normal operation | 118–125 psi | 390–420 psi |\\n| Low charge | <110 psi | <350 psi |\\n| High charge / restriction | >135 psi | >450 psi |","wordCount":44},{"id":"r410a-refrigerant-safety_chunk_5","docId":"r410a-refrigerant-safety","docTitle":"R-410A Refrigerant Safety","sourceType":"manual","headingPath":["R-410A Refrigerant Safety","Recovery Procedure"],"text":"1. Connect recovery machine to system\\n2. Recover to 0 psi or lower (pull to vacuum if possible)\\n3. Record weight of recovered refrigerant on work order\\n4. Use only certified recovery cylinders","wordCount":33},{"id":"refrigerant-leak-detection_chunk_0","docId":"refrigerant-leak-detection","docTitle":"Refrigerant Leak Detection","sourceType":"manual","headingPath":["Refrigerant Leak Detection","Methods of Detection","4. Ultrasonic Detector"],"text":"### 1. Electronic Leak Detector\\n**Best for:** Finding leaks quickly, especially in hard-to-see areas.\\n- Heated diode detectors respond to halogenated compounds\\n- Infrared detectors are more sensitive and have fewer false alarms\\n- Move probe slowly (~1 inch/second) around suspected areas\\n- Start at bottom of components (refrigerant vapor is heavier than air at low concentrations)\\n\\n### 2. Fluorescent Dye\\n**Best for:** Confirming leak location, recurring leaks.\\n- UV dye injected into system circulates with oil and marks leak points\\n- Use manufacturer-approved dye (avoid generic dyes in warranty equipment)\\n- Requires UV lamp for detection\\n- Record dye injection on service sticker for future techs\\n\\n### 3. Soap Bubbles\\n**Best for:** Pressurized system checks, verifying repairs.\\n- Apply nitrogen-purged system pressure before using (never pressurize with system refrigerant for leak check alone)\\n- Use approved leak detection soap — standard dish soap can be corrosive\\n- Good for accessible fittings and brazed joints\\n\\n### 4. Ultrasonic Detector\\n**Best for:** Large leaks, pressurized lines.","wordCount":165},{"id":"refrigerant-leak-detection_chunk_1","docId":"refrigerant-leak-detection","docTitle":"Refrigerant Leak Detection","sourceType":"manual","headingPath":["Refrigerant Leak Detection","Common Leak Locations (by frequency)"],"text":"1. Schrader valve cores (check first — quick fix)\\n2. Flare fittings at service valves\\n3. Brazed joints at coil connections\\n4. Evaporator coil — corrosion (formicary corrosion in copper coils)\\n5. Condenser coil — impact damage or vibration cracks","wordCount":40},{"id":"refrigerant-leak-detection_chunk_2","docId":"refrigerant-leak-detection","docTitle":"Refrigerant Leak Detection","sourceType":"manual","headingPath":["Refrigerant Leak Detection","Formicary Corrosion"],"text":"A specific problem with copper evaporator coils in newer construction:\\n- Caused by formic acid + water + oxygen reacting with copper\\n- Forms pinholes in coil walls, often undetectable visually\\n- More common with newer homes using VOC-emitting materials\\n- Solution: aluminum coils or coil coating products","wordCount":48},{"id":"refrigerant-leak-detection_chunk_3","docId":"refrigerant-leak-detection","docTitle":"Refrigerant Leak Detection","sourceType":"manual","headingPath":["Refrigerant Leak Detection","Documenting Leaks"],"text":"Always document: location found, method used, refrigerant type, amount added. Per EPA regulations, systems over 50 lbs charge must have leaks repaired within 30 days (HVACR systems) if annual leak rate exceeds 30%.","wordCount":33},{"id":"seer2-ratings-explained_chunk_0","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","What is SEER2?"],"text":"**SEER2** (Seasonal Energy Efficiency Ratio 2) is the updated efficiency standard for residential AC and heat pump equipment, effective January 1, 2023. It replaced the original SEER rating.\\n\\nSEER2 uses a more realistic test procedure (M1 test method) that accounts for static pressure in ductwork, resulting in ratings approximately 4–7% lower than equivalent SEER equipment.","wordCount":55},{"id":"seer2-ratings-explained_chunk_1","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","Minimum Efficiency Requirements (2023+)"],"text":"| Region | Minimum SEER2 (AC) | Minimum SEER2 (Heat Pump) |\\n|--------|-------------------|--------------------------|\\n| Southeast (including Texas) | 15.2 | 15.2 |\\n| Southwest | 15.2 | 15.2 |\\n| North | 13.4 | 14.3 |\\n\\nTexas falls in the **Southeast/Southwest** region — minimum is **15.2 SEER2**.","wordCount":47},{"id":"seer2-ratings-explained_chunk_2","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","SEER2 to Energy Savings"],"text":"| SEER2 Rating | Annual Estimated Savings vs. 10 SEER |\\n|-------------|--------------------------------------|\\n| 14 SEER2 | ~29% energy reduction |\\n| 16 SEER2 | ~38% energy reduction |\\n| 18 SEER2 | ~44% energy reduction |\\n| 20 SEER2 | ~50% energy reduction |\\n\\n*Based on average Austin TX usage (2,000+ cooling hours/year)*","wordCount":53},{"id":"seer2-ratings-explained_chunk_3","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","SEER vs SEER2 Conversion (Approximate)"],"text":"Multiply SEER by 0.95 to estimate the SEER2 equivalent:\\n- 16 SEER ≈ 15.2 SEER2\\n- 18 SEER ≈ 17.1 SEER2\\n- 20 SEER ≈ 19.0 SEER2","wordCount":27},{"id":"seer2-ratings-explained_chunk_4","docId":"seer2-ratings-explained","docTitle":"SEER2 Ratings Explained","sourceType":"manual","headingPath":["SEER2 Ratings Explained","Communicating Value to Customers"],"text":"- A 16-year-old 10 SEER unit replaced with a 16 SEER2 unit cuts cooling costs by ~38%\\n- In Austin\'s climate, a typical home saves $300–600/year in cooling costs\\n- Most new equipment qualifies for the **25C federal tax credit** (up to $600 for heat pumps and AC meeting efficiency thresholds)","wordCount":51},{"id":"thermostat-wiring-guide_chunk_0","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Standard Wire Color Codes"],"text":"| Wire Color | Terminal | Function |\\n|-----------|----------|----------|\\n| Red | R or Rh/Rc | 24V power from transformer |\\n| Green | G | Fan (indoor blower) |\\n| Yellow | Y | Compressor / cooling |\\n| White | W | Heat (gas valve or aux heat) |\\n| Blue or Black | C | Common (24V return) |\\n| Orange | O | Reversing valve (heat pumps — energized in cooling) |\\n| Dark Blue | B | Reversing valve (Carrier/Bryant — energized in heating) |","wordCount":90},{"id":"thermostat-wiring-guide_chunk_1","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Common Configurations","Heat Pump (7-wire)"],"text":"### Standard AC + Gas Furnace (5-wire)\\n```\\nR — Rh (or R)\\nG — G\\nY — Y\\nW — W\\nC — C\\n```\\n\\n### Heat Pump (7-wire)\\n```\\nR — R\\nG — G\\nY — Y\\nO — O (or B for Carrier)\\nW — W (aux heat)\\nC — C\\nE — E (emergency heat)\\n```","wordCount":61},{"id":"thermostat-wiring-guide_chunk_2","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Troubleshooting"],"text":"| Symptom | Likely Wiring Cause |\\n|---------|-------------------|\\n| Fan runs but no cooling | Y wire loose or open |\\n| Cooling but fan won\'t turn off | G wire shorted to R |\\n| No heat, no cooling | R wire open or blown fuse |\\n| Heat pump blows cold in heat mode | O/B wire reversed or missing |\\n| Short cycling | C wire missing (wifi thermostat drawing power from Y) |","wordCount":77},{"id":"thermostat-wiring-guide_chunk_3","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Installing a Smart Thermostat Without C-Wire"],"text":"Many smart thermostats (Nest, Ecobee) require a C wire for continuous 24V power. Options when no C wire exists:\\n1. **Run a new wire** — best solution if accessible\\n2. **Use a C-wire adapter** (some brands include one)\\n3. **Use the G terminal** as C and enable \\"fan always on\\" mode (not recommended for most customers)\\n4. **Install a 24V plug-in transformer** at the air handler","wordCount":66},{"id":"thermostat-wiring-guide_chunk_4","docId":"thermostat-wiring-guide","docTitle":"Thermostat Wiring Guide","sourceType":"guide","headingPath":["Thermostat Wiring Guide","Important Notes"],"text":"- Always disconnect power at disconnect box before working on wiring\\n- Rh and Rc are separate terminals on some thermostats — jumper them if the system has a single R wire\\n- Never connect 24V control wires to line voltage (120V/240V) terminals","wordCount":43},{"id":"warranty-terms_chunk_0","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","Labor Warranty"],"text":"All repair work performed by Northwind technicians carries a **90-day labor warranty** from the date of service. If the same failure recurs within 90 days, we return at no additional labor charge.\\n\\n**Exclusions:**\\n- Failures caused by misuse, neglect, or unauthorized repairs\\n- Failures caused by electrical surges or water damage\\n- Filter changes and routine consumables","wordCount":57},{"id":"warranty-terms_chunk_1","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","Parts Warranty"],"text":"Parts installed by Northwind are covered by the manufacturer\'s warranty, passed through to the customer. Common terms:\\n\\n| Part Type | Typical Warranty |\\n|----------|-----------------|\\n| Compressor | 5–10 years (registered) |\\n| Capacitor | 1 year manufacturer |\\n| Contactor | 1 year manufacturer |\\n| Control board | 5 years (varies by brand) |\\n| Motors (blower, fan) | 5 years (varies) |","wordCount":65},{"id":"warranty-terms_chunk_2","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","Equipment Warranty (New Installs)","Northwind Install Labor Warranty"],"text":"### Carrier Equipment (registered within 90 days of install)\\n- **Compressor:** 10 years\\n- **All other covered components:** 10 years\\n- **Heat exchanger (furnace):** Lifetime\\n\\n**Important:** Registration must be completed at [carrier.com](https://carrier.com/residential/en/us/register-my-product/) within 90 days of installation. Unregistered units revert to 5-year parts warranty.\\n\\n### Northwind Install Labor Warranty\\n- 1 year on installation labor for new equipment","wordCount":58},{"id":"warranty-terms_chunk_3","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","How to File a Warranty Claim"],"text":"1. Call Northwind at 555-0100 or use the customer portal\\n2. Provide: original invoice number, model, serial number, description of issue\\n3. We will assess warranty eligibility and schedule service\\n4. Manufacturer warranty claims require proof of original installation date","wordCount":40},{"id":"warranty-terms_chunk_4","docId":"warranty-terms","docTitle":"Northwind Heating & Air — Warranty Terms","sourceType":"policy","headingPath":["Northwind Heating & Air — Warranty Terms","Out-of-Warranty Equipment"],"text":"For equipment older than 10 years with significant repair costs, we recommend requesting a replacement estimate. Units older than 12 years rarely justify major repairs economically.","wordCount":26}],"totalDocs":16,"totalChunks":77,"builtAt":"2026-10-03T15:40:24.900Z"}')}}]);